export function fixture(name) {
    if (!Object.prototype.hasOwnProperty.call(FIXTURES, name)) throw new Error("no fixture " + name)
    return FIXTURES[name]
}

export function fixtureNames(prefix) {
    return Object.keys(FIXTURES).filter(function (k) { return k.indexOf(prefix) === 0 })
}
